<?php
require_once __DIR__.'/../auth/check.php';requireRole('Admin');require_once __DIR__.'/../config/database.php';
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';$id=(int)($_POST['MaThuoc']??0);
 try{
  if($action==='save'){$ten=trim($_POST['TenThuoc']??'');$dv=trim($_POST['DonVi']??'');$sl=(int)($_POST['SoLuongTon']??0);$gia=(float)($_POST['DonGia']??0);$hsd=$_POST['HanSuDung']?:null;if($ten==='')throw new Exception('Tên thuốc là bắt buộc.');if($sl<0||$gia<0)throw new Exception('Số lượng và đơn giá không được âm.');if($id){$pdo->prepare('UPDATE Thuoc SET TenThuoc=?,DonVi=?,SoLuongTon=?,DonGia=?,HanSuDung=? WHERE MaThuoc=?')->execute([$ten,$dv?:null,$sl,$gia,$hsd,$id]);}else{$pdo->prepare('INSERT INTO Thuoc(TenThuoc,DonVi,SoLuongTon,DonGia,HanSuDung) VALUES(?,?,?,?,?)')->execute([$ten,$dv?:null,$sl,$gia,$hsd]);}}
  elseif($action==='toggle'&&$id){$pdo->prepare('UPDATE Thuoc SET TrangThai=1-TrangThai WHERE MaThuoc=?')->execute([$id]);}
  header('Location: medicines.php');exit;
 }catch(Throwable $e){$error=$e->getMessage();}
}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM Thuoc WHERE MaThuoc=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$pdo->query('SELECT * FROM Thuoc ORDER BY MaThuoc DESC')->fetchAll();
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thuốc</title><link href="../assets/vendor/bootstrap/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><div class="d-flex justify-content-between mb-3"><h2>Quản lý thuốc</h2><a href="dashboard.php" class="btn btn-outline-secondary">Dashboard</a></div><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?>
<form method="post" class="card card-body mb-4"><input type="hidden" name="action" value="save"><input type="hidden" name="MaThuoc" value="<?=$edit['MaThuoc']??''?>"><div class="row g-2"><div class="col-md-3"><input name="TenThuoc" class="form-control" placeholder="Tên thuốc" required value="<?=htmlspecialchars($edit['TenThuoc']??'')?>"></div><div class="col-md-2"><input name="DonVi" class="form-control" placeholder="Đơn vị" value="<?=htmlspecialchars($edit['DonVi']??'')?>"></div><div class="col-md-2"><input type="number" min="0" name="SoLuongTon" class="form-control" placeholder="Tồn kho" value="<?=$edit['SoLuongTon']??0?>"></div><div class="col-md-2"><input type="number" min="0" step="0.01" name="DonGia" class="form-control" placeholder="Đơn giá" value="<?=$edit['DonGia']??0?>"></div><div class="col-md-2"><input type="date" name="HanSuDung" class="form-control" value="<?=$edit['HanSuDung']??''?>"></div><div class="col-md-1"><button class="btn btn-primary w-100"><?=$edit?'Lưu':'Thêm'?></button></div></div></form>
<table class="table table-bordered align-middle"><thead><tr><th>Mã</th><th>Tên thuốc</th><th>Đơn vị</th><th>Tồn kho</th><th>Đơn giá</th><th>HSD</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['MaThuoc']?></td><td><?=htmlspecialchars($r['TenThuoc'])?></td><td><?=htmlspecialchars($r['DonVi']??'')?></td><td><?=$r['SoLuongTon']?></td><td><?=number_format($r['DonGia'],0,',','.')?></td><td><?=$r['HanSuDung']??''?></td><td><?=$r['TrangThai']?'Đang dùng':'Đã khóa'?></td><td><a class="btn btn-sm btn-warning" href="?edit=<?=$r['MaThuoc']?>">Sửa</a> <form class="d-inline" method="post"><input type="hidden" name="action" value="toggle"><input type="hidden" name="MaThuoc" value="<?=$r['MaThuoc']?>"><button class="btn btn-sm <?=$r['TrangThai']?'btn-outline-danger':'btn-outline-success'?>"><?=$r['TrangThai']?'Khóa':'Mở'?></button></form></td></tr><?php endforeach;?></tbody></table></div></body></html>
